use std::env;
use std::path::PathBuf;

pub const MAX_AGE: f64 = 10000.0;

pub fn data_dir() -> PathBuf {
    if let Ok(dir) = env::var("_ZO_DATA_DIR") {
        return PathBuf::from(dir);
    }

    #[cfg(target_os = "macos")]
    {
        if let Some(home) = dirs::home_dir() {
            return home.join("Library").join("Application Support");
        }
    }

    // Linux/BSD: XDG_DATA_HOME or $HOME/.local/share
    if let Ok(xdg) = env::var("XDG_DATA_HOME") {
        return PathBuf::from(xdg);
    }

    if let Some(home) = dirs::home_dir() {
        return home.join(".local").join("share");
    }

    PathBuf::from(".")
}

pub fn db_path() -> PathBuf {
    data_dir().join("db.zo")
}

pub fn max_age() -> f64 {
    env::var("_ZO_MAXAGE")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(MAX_AGE)
}

pub fn resolve_symlinks() -> bool {
    env::var("_ZO_RESOLVE_SYMLINKS").as_deref() == Ok("1")
}

pub fn echo() -> bool {
    env::var("_ZO_ECHO").as_deref() == Ok("1")
}

pub fn exclude_dirs() -> Vec<String> {
    let default = dirs::home_dir()
        .map(|h| h.to_string_lossy().to_string())
        .unwrap_or_default();

    let raw = env::var("_ZO_EXCLUDE_DIRS").unwrap_or(default);
    if raw.is_empty() {
        return vec![];
    }

    // Split by ":" on Unix
    raw.split(':')
        .map(|s| s.to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

pub fn fzf_opts() -> Option<String> {
    env::var("_ZO_FZF_OPTS").ok()
}
RUST_EOF

