use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

use crate::error::{Error, Result};

const MAGIC: u32 = 3;

#[derive(Debug, Clone)]
pub struct Entry {
    pub path: String,
    pub rank: f64,
    pub timestamp: u64,
}

impl Entry {
    pub fn new(path: String, rank: f64, timestamp: u64) -> Self {
        Entry { path, rank, timestamp }
    }

    pub fn frecency(&self, now: u64) -> f64 {
        let age = now.saturating_sub(self.timestamp);
        let multiplier = if age <= 3600 {
            4.0
        } else if age <= 86400 {
            2.0
        } else if age <= 604800 {
            0.5
        } else {
            0.25
        };
        self.rank * multiplier
    }
}

pub struct Database {
    pub entries: Vec<Entry>,
}

impl Database {
    pub fn new() -> Self {
        Database { entries: vec![] }
    }

    pub fn load(path: &Path) -> Result<Self> {
        match fs::read(path) {
            Ok(data) => Self::parse(&data),
            Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(Self::new()),
            Err(e) => Err(Error(format!("could not read database: {}", e))),
        }
    }

    fn parse(data: &[u8]) -> Result<Self> {
        if data.len() < 12 {
            return Ok(Self::new());
        }

        let magic = read_u32(data, 0)?;
        if magic != MAGIC {
            return Err(Error(format!("invalid database magic: {}", magic)));
        }

        let count = read_u64(data, 4)? as usize;
        let mut pos = 12;
        let mut entries = Vec::with_capacity(count);

        for _ in 0..count {
            if pos + 8 > data.len() {
                break;
            }
            let path_len = read_u64(data, pos)? as usize;
            pos += 8;

            if pos + path_len > data.len() {
                break;
            }
            let path = String::from_utf8(data[pos..pos+path_len].to_vec())
                .map_err(|e| Error(format!("invalid path: {}", e)))?;
            pos += path_len;

            if pos + 16 > data.len() {
                break;
            }
            let rank = read_f64(data, pos)?;
            pos += 8;
            let timestamp = read_u64(data, pos)?;
            pos += 8;

            entries.push(Entry { path, rank, timestamp });
        }

        Ok(Database { entries })
    }

    pub fn save(&self, path: &Path) -> Result<()> {
        // Ensure directory exists
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)
                .map_err(|e| Error(format!("could not create data directory: {}", e)))?;
        }

        let mut buf = Vec::new();

        // Magic
        buf.extend_from_slice(&MAGIC.to_le_bytes());
        // Count
        buf.extend_from_slice(&(self.entries.len() as u64).to_le_bytes());

        for entry in &self.entries {
            let path_bytes = entry.path.as_bytes();
            buf.extend_from_slice(&(path_bytes.len() as u64).to_le_bytes());
            buf.extend_from_slice(path_bytes);
            buf.extend_from_slice(&entry.rank.to_le_bytes());
            buf.extend_from_slice(&entry.timestamp.to_le_bytes());
        }

        // Write atomically using temp file
        let tmp_path = path.with_extension("zo.tmp");
        fs::write(&tmp_path, &buf)
            .map_err(|e| Error(format!("could not write database: {}", e)))?;
        fs::rename(&tmp_path, path)
            .map_err(|e| Error(format!("could not update database: {}", e)))?;

        Ok(())
    }

    pub fn add(&mut self, path: &str, score_increment: f64, max_age: f64) {
        let now = current_time();

        // Find existing entry or add new one
        if let Some(entry) = self.entries.iter_mut().find(|e| e.path == path) {
            entry.rank += score_increment;
            entry.timestamp = now;
        } else {
            self.entries.push(Entry {
                path: path.to_string(),
                rank: score_increment,
                timestamp: now,
            });
        }

        // Apply aging if total exceeds max_age
        let total: f64 = self.entries.iter().map(|e| e.rank).sum();
        if total > max_age {
            let factor = max_age / total;
            self.entries.iter_mut().for_each(|e| e.rank *= factor);
            // Remove entries with rank < 1.0
            self.entries.retain(|e| e.rank >= 1.0);
        }
    }

    pub fn remove(&mut self, path: &str) -> bool {
        let before = self.entries.len();
        self.entries.retain(|e| e.path != path);
        self.entries.len() < before
    }

    pub fn query<'a>(&'a self, keywords: &[String], exclude: Option<&str>, base_dir: Option<&str>, all: bool) -> Vec<&'a Entry> {
        let now = current_time();

        let mut results: Vec<&Entry> = self.entries.iter()
            .filter(|e| {
                // Filter by existence (unless --all)
                if !all && !Path::new(&e.path).is_dir() {
                    return false;
                }
                // Filter excluded path
                if let Some(exc) = exclude {
                    if e.path == exc {
                        return false;
                    }
                }
                // Filter base_dir
                if let Some(base) = base_dir {
                    if !e.path.starts_with(base) {
                        return false;
                    }
                }
                // Match keywords
                if !keywords.is_empty() && !matches_keywords(&e.path, keywords) {
                    return false;
                }
                true
            })
            .collect();

        // Sort by frecency descending, then by timestamp descending
        results.sort_by(|a, b| {
            let fa = a.frecency(now);
            let fb = b.frecency(now);
            fb.partial_cmp(&fa).unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| b.timestamp.cmp(&a.timestamp))
        });

        results
    }
}

pub fn current_time() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

fn read_u32(data: &[u8], pos: usize) -> Result<u32> {
    if pos + 4 > data.len() {
        return Err(Error("unexpected end of database".to_string()));
    }
    Ok(u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]))
}

fn read_u64(data: &[u8], pos: usize) -> Result<u64> {
    if pos + 8 > data.len() {
        return Err(Error("unexpected end of database".to_string()));
    }
    Ok(u64::from_le_bytes([
        data[pos], data[pos+1], data[pos+2], data[pos+3],
        data[pos+4], data[pos+5], data[pos+6], data[pos+7]
    ]))
}

fn read_f64(data: &[u8], pos: usize) -> Result<f64> {
    if pos + 8 > data.len() {
        return Err(Error("unexpected end of database".to_string()));
    }
    Ok(f64::from_le_bytes([
        data[pos], data[pos+1], data[pos+2], data[pos+3],
        data[pos+4], data[pos+5], data[pos+6], data[pos+7]
    ]))
}

/// Check if a path matches all keywords.
/// Matching algorithm:
/// - Split path by "/" to get components
/// - For each keyword, split by "/" to get keyword parts
/// - Each keyword's parts must match consecutive adjacent path components
///   (case-insensitive substring matching)
/// - The last non-empty part of the last keyword must match at the last path component position
/// - Keywords are matched in order (each keyword's first part starts after previous keyword's last match)
pub fn matches_keywords(path: &str, keywords: &[String]) -> bool {
    let path_components: Vec<&str> = path.split('/').collect();
    let n = path_components.len();

    if n == 0 {
        return false;
    }

    // Current position in path_components (exclusive, where we must start from)
    let mut pos: usize = 0;

    for (ki, keyword) in keywords.iter().enumerate() {
        let is_last_keyword = ki == keywords.len() - 1;
        let kw_parts: Vec<&str> = keyword.split('/').collect();

        // All parts (including empty ones) - used for the adjacency rule
        // Find starting position in path where kw_parts match consecutively

        let found = find_keyword_match(&path_components, &kw_parts, pos, is_last_keyword, n);

        match found {
            Some(end_pos) => {
                pos = end_pos + 1; // Next keyword must start after this position
            }
            None => return false,
        }
    }

    true
}

/// Find where keyword parts match in path_components, starting from `start_pos`.
/// Returns the index of the last matched component if found.
/// 
/// For the last keyword: the last non-empty part must match path_components[n-1] (last component).
/// For non-last keywords: the last matched position can be anywhere < n-1.
fn find_keyword_match(
    path_components: &[&str],
    kw_parts: &[&str],
    start_pos: usize,
    is_last_keyword: bool,
    n: usize,
) -> Option<usize> {
    let num_parts = kw_parts.len();
    if num_parts == 0 {
        return Some(start_pos.saturating_sub(1));
    }

    // For each possible starting position p in path_components
    // The match requires kw_parts[0] at p, kw_parts[1] at p+1, ..., kw_parts[num_parts-1] at p+num_parts-1

    // Constraint: if is_last_keyword, the last non-empty part must match at position n-1

    // Find the last non-empty part index
    let last_nonempty_idx = kw_parts.iter().rposition(|p| !p.is_empty());

    if is_last_keyword {
        // The last non-empty part of this keyword must be at path position n-1
        // So if last non-empty is at kw index `li`, then it matches path at n-1
        // meaning the first part matches at path[n-1 - li]

        match last_nonempty_idx {
            None => {
                // All parts are empty - matches trivially at any position
                // Return start_pos - 1 meaning it matches at start
                return Some(n - 1);
            }
            Some(li) => {
                // The last non-empty part is at kw_parts[li]
                // It must match path_components[n-1]
                // So start of keyword is at path position: n-1-li .. but we need to be careful
                // Actually: if we start the keyword match at path position p,
                // then kw_parts[li] matches at path position p+li = n-1
                // => p = n-1-li

                // But we also need the remaining parts (after li) which are all empty
                // Empty parts always match (empty string is substring of anything)
                // BUT they must match at consecutive positions p+li+1, p+li+2, ...
                // The last one must be at n-1? No wait...

                // Actually, the constraint is: the last position matched is n-1
                // with the "consecutive" adjacency rule, the positions are p, p+1, ..., p+num_parts-1
                // The last non-empty position is p+li
                // The final position is p+num_parts-1
                // The final position must equal n-1 (last path component)

                let p = n as isize - num_parts as isize;
                if p < 0 || (p as usize) < start_pos {
                    return None;
                }
                let p = p as usize;

                // Verify all parts match
                for (i, part) in kw_parts.iter().enumerate() {
                    let path_idx = p + i;
                    if path_idx >= n {
                        return None;
                    }
                    if !part.is_empty() && !contains_ci(path_components[path_idx], part) {
                        return None;
                    }
                }

                return Some(p + num_parts - 1);
            }
        }
    } else {
        // Not last keyword - find any valid starting position >= start_pos
        // The last position matched can be anywhere (not required to be n-1)
        // BUT to leave room for subsequent keywords, we want to allow room

        // Try each possible starting position
        let max_start = if n >= num_parts { n - num_parts } else { return None; };

        for p in start_pos..=max_start {
            let mut ok = true;
            for (i, part) in kw_parts.iter().enumerate() {
                let path_idx = p + i;
                if path_idx >= n {
                    ok = false;
                    break;
                }
                if !part.is_empty() && !contains_ci(path_components[path_idx], part) {
                    ok = false;
                    break;
                }
            }
            if ok {
                return Some(p + num_parts - 1);
            }
        }

        None
    }
}

fn contains_ci(haystack: &str, needle: &str) -> bool {
    if needle.is_empty() {
        return true;
    }
    let h = haystack.to_lowercase();
    let n = needle.to_lowercase();
    h.contains(&n as &str)
}
