use std::path::Path;
use std::process;

use crate::cmd::{Cli, Command, ImportFrom};
use crate::config;
use crate::db::{Database, Entry};
use crate::error::{Error, Result};
use crate::init;
use clap::Parser;

pub fn run() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Command::Add(cmd) => run_add(cmd),
        Command::Edit => run_edit(),
        Command::Import(cmd) => run_import(cmd),
        Command::Init(cmd) => run_init(cmd),
        Command::Query(cmd) => run_query(cmd),
        Command::Remove(cmd) => run_remove(cmd),
    }
}

fn run_add(cmd: crate::cmd::CmdAdd) -> Result<()> {
    let score_increment = cmd.score.unwrap_or(1.0);
    let exclude_dirs = config::exclude_dirs();
    let resolve_symlinks = config::resolve_symlinks();
    let max_age = config::max_age();
    let db_path = config::db_path();

    let mut db = Database::load(&db_path)?;
    let mut modified = false;

    for path_str in &cmd.paths {
        let path = Path::new(path_str);

        // Check if it's a directory
        let canonical = if resolve_symlinks {
            match path.canonicalize() {
                Ok(p) => p,
                Err(_) => {
                    eprintln!("zoxide: not a directory: {}", path_str);
                    process::exit(1);
                }
            }
        } else {
            // Use the path as-is but verify it's a directory
            if !path.is_dir() {
                eprintln!("zoxide: not a directory: {}", path_str);
                process::exit(1);
            }
            path.to_path_buf()
        };

        if !canonical.is_dir() {
            eprintln!("zoxide: not a directory: {}", path_str);
            process::exit(1);
        }

        let canonical_str = canonical.to_string_lossy().to_string();

        // Check exclusions
        if is_excluded(&canonical_str, &exclude_dirs) {
            continue;
        }

        db.add(&canonical_str, score_increment, max_age);
        modified = true;
    }

    if modified || cmd.paths.is_empty() {
        db.save(&db_path)?;
    } else {
        // Even if no entries added (all excluded), save if DB was loaded/modified
        db.save(&db_path)?;
    }

    Ok(())
}

fn is_excluded(path: &str, exclude_dirs: &[String]) -> bool {
    for pattern in exclude_dirs {
        if glob_match(pattern, path) {
            return true;
        }
    }
    false
}

fn glob_match(pattern: &str, path: &str) -> bool {
    // Use glob crate for pattern matching
    match glob::Pattern::new(pattern) {
        Ok(pat) => pat.matches(path),
        Err(_) => pattern == path,
    }
}

fn run_edit() -> Result<()> {
    let db_path = config::db_path();
    let db = Database::load(&db_path)?;

    // Prepare list of paths for fzf
    let now = crate::db::current_time();
    let mut entries: Vec<&Entry> = db.entries.iter()
        .filter(|e| Path::new(&e.path).is_dir())
        .collect();

    entries.sort_by(|a, b| {
        let fa = a.frecency(now);
        let fb = b.frecency(now);
        fb.partial_cmp(&fa).unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| b.timestamp.cmp(&a.timestamp))
    });

    let fzf_input: String = entries.iter()
        .map(|e| format!("{:>6.1} {}", e.frecency(now), e.path))
        .collect::<Vec<_>>()
        .join("\n");

    // Run fzf
    let fzf_opts = config::fzf_opts();
    let selected = run_fzf_multi(&fzf_input, fzf_opts.as_deref())?;

    if selected.is_empty() {
        return Ok(());
    }

    // Parse selected entries and remove them
    let mut db = Database::load(&db_path)?;
    for line in selected.lines() {
        // Parse "  score path" format
        if let Some(path) = line.trim_start().splitn(2, ' ').nth(1) {
            let path = path.trim_start();
            if !db.remove(path) {
                // Try without score prefix (in case format differs)
                db.remove(line);
            }
        }
    }

    db.save(&db_path)?;
    Ok(())
}

fn run_fzf_multi(input: &str, opts: Option<&str>) -> Result<String> {
    use std::process::{Command, Stdio};
    use std::io::Write;

    // Check if fzf is available
    let fzf = std::process::Command::new("fzf").arg("--version").output();
    if fzf.is_err() {
        return Err(Error("could not find fzf, is it installed?".to_string()));
    }

    let mut args = vec!["--multi", "--no-sort"];
    let opts_str;
    if let Some(o) = opts {
        opts_str = o.to_string();
        // Split opts string into args
        // Simple splitting by whitespace
        for arg in opts_str.split_whitespace() {
            args.push(arg);
        }
    }

    let mut child = Command::new("fzf")
        .args(&args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .map_err(|_| Error("could not find fzf, is it installed?".to_string()))?;

    if let Some(stdin) = child.stdin.take() {
        let mut stdin = stdin;
        let _ = stdin.write_all(input.as_bytes());
    }

    let output = child.wait_with_output()
        .map_err(|e| Error(format!("fzf error: {}", e)))?;

    Ok(String::from_utf8_lossy(&output.stdout).to_string())
}

fn run_fzf_single(input: &str, opts: Option<&str>) -> Result<String> {
    use std::process::{Command, Stdio};
    use std::io::Write;

    // Check if fzf is available
    let fzf_check = std::process::Command::new("fzf").arg("--version").output();
    if fzf_check.is_err() {
        return Err(Error("could not find fzf, is it installed?".to_string()));
    }

    let mut args: Vec<String> = vec!["--no-sort".to_string()];
    if let Some(o) = opts {
