package main

import (
	"bufio"
	"encoding/binary"
	"fmt"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

const version = "0.9.9"
const author = "Ajeet D'Souza <98ajeet@gmail.com>"
const magic uint32 = 3

type Entry struct {
	Path      string
	Rank      float64
	Timestamp uint64
}

func (e *Entry) Frecency(now uint64) float64 {
	var age uint64
	if now > e.Timestamp {
		age = now - e.Timestamp
	}
	var mult float64
	switch {
	case age <= 3600:
		mult = 4.0
	case age <= 86400:
		mult = 2.0
	case age <= 604800:
		mult = 0.5
	default:
		mult = 0.25
	}
	return e.Rank * mult
}

type Database struct {
	Entries []*Entry
}

func NewDatabase() *Database {
	return &Database{}
}

func LoadDatabase(path string) (*Database, error) {
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return NewDatabase(), nil
	}
	if err != nil {
		return nil, fmt.Errorf("could not read database: %w", err)
	}
	return parseDatabase(data)
}

func parseDatabase(data []byte) (*Database, error) {
	if len(data) < 12 {
		return NewDatabase(), nil
	}
	m := binary.LittleEndian.Uint32(data[0:4])
	if m != magic {
		return nil, fmt.Errorf("invalid database magic: %d", m)
	}
	count := binary.LittleEndian.Uint64(data[4:12])
	pos := 12
	entries := make([]*Entry, 0, count)
	for i := uint64(0); i < count; i++ {
		if pos+8 > len(data) {
			break
		}
		pathLen := int(binary.LittleEndian.Uint64(data[pos : pos+8]))
		pos += 8
		if pos+pathLen > len(data) {
			break
		}
		path := string(data[pos : pos+pathLen])
		pos += pathLen
		if pos+16 > len(data) {
			break
		}
		rank := math.Float64frombits(binary.LittleEndian.Uint64(data[pos : pos+8]))
		pos += 8
		ts := binary.LittleEndian.Uint64(data[pos : pos+8])
		pos += 8
		entries = append(entries, &Entry{Path: path, Rank: rank, Timestamp: ts})
	}
	return &Database{Entries: entries}, nil
}

func (db *Database) Save(path string) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("could not create data directory: %w", err)
	}

	buf := make([]byte, 0, 12+len(db.Entries)*50)
	var tmp [8]byte

	binary.LittleEndian.PutUint32(tmp[:4], magic)
	buf = append(buf, tmp[:4]...)
	binary.LittleEndian.PutUint64(tmp[:8], uint64(len(db.Entries)))
	buf = append(buf, tmp[:8]...)

	for _, e := range db.Entries {
		pathBytes := []byte(e.Path)
		binary.LittleEndian.PutUint64(tmp[:8], uint64(len(pathBytes)))
		buf = append(buf, tmp[:8]...)
		buf = append(buf, pathBytes...)
		binary.LittleEndian.PutUint64(tmp[:8], math.Float64bits(e.Rank))
		buf = append(buf, tmp[:8]...)
		binary.LittleEndian.PutUint64(tmp[:8], e.Timestamp)
		buf = append(buf, tmp[:8]...)
	}

	tmpPath := path + ".tmp"
	if err := os.WriteFile(tmpPath, buf, 0644); err != nil {
		return fmt.Errorf("could not write database: %w", err)
	}
	if err := os.Rename(tmpPath, path); err != nil {
		return fmt.Errorf("could not update database: %w", err)
	}
	return nil
}

func (db *Database) Add(path string, scoreIncrement float64, maxAge float64) {
	now := currentTime()

	found := false
	for _, e := range db.Entries {
		if e.Path == path {
			e.Rank += scoreIncrement
			e.Timestamp = now
			found = true
			break
		}
	}
	if !found {
		db.Entries = append(db.Entries, &Entry{Path: path, Rank: scoreIncrement, Timestamp: now})
	}

	total := 0.0
	for _, e := range db.Entries {
		total += e.Rank
	}
	if total > maxAge {
		factor := maxAge / total
		newEntries := make([]*Entry, 0, len(db.Entries))
		for _, e := range db.Entries {
			e.Rank *= factor
			if e.Rank >= 1.0 {
				newEntries = append(newEntries, e)
			}
		}
		db.Entries = newEntries
	}
}

func (db *Database) Remove(path string) bool {
	newEntries := make([]*Entry, 0, len(db.Entries))
	found := false
	for _, e := range db.Entries {
		if e.Path == path {
			found = true
		} else {
			newEntries = append(newEntries, e)
		}
	}
	db.Entries = newEntries
	return found
}

func (db *Database) Query(keywords []string, exclude string, baseDir string, all bool) []*Entry {
	now := currentTime()

	var results []*Entry
	for _, e := range db.Entries {
		if !all {
			info, err := os.Stat(e.Path)
			if err != nil || !info.IsDir() {
				continue
			}
		}
		if exclude != "" && e.Path == exclude {
			continue
		}
		if baseDir != "" && !strings.HasPrefix(e.Path, baseDir) {
			continue
		}
		if len(keywords) > 0 && !matchesKeywords(e.Path, keywords) {
			continue
		}
		results = append(results, e)
	}

	sort.Slice(results, func(i, j int) bool {
		fi := results[i].Frecency(now)
		fj := results[j].Frecency(now)
		if fi != fj {
			return fi > fj
		}
		return results[i].Timestamp > results[j].Timestamp
	})
	return results
}

func currentTime() uint64 {
	return uint64(time.Now().Unix())
}

// matchesKeywords checks if a path matches all keywords using the zoxide matching algorithm:
// - Keywords are matched in order
// - "/" within a keyword requires adjacent path components
// - All parts are case-insensitive substring matches against path components
// - The last non-empty part of the last keyword must match the last path component
func matchesKeywords(path string, keywords []string) bool {
	components := strings.Split(path, "/")
	n := len(components)
	if n == 0 {
		return false
	}

	pos := 0
	for ki, keyword := range keywords {
		isLast := ki == len(keywords)-1
		parts := strings.Split(keyword, "/")

		endPos, ok := findKeywordMatch(components, parts, pos, isLast, n)
		if !ok {
			return false
		}
		pos = endPos + 1
	}
	return true
}

// findKeywordMatch finds where keyword parts match in path components starting from startPos.
// Returns (endPos, true) if found, (0, false) otherwise.
// For last keyword: last part must match at position n-1.
// For non-last keywords: can match anywhere from startPos onward.
// "/" within keyword requires ADJACENT path components.
func findKeywordMatch(components []string, parts []string, startPos int, isLast bool, n int) (int, bool) {
	numParts := len(parts)
	if numParts == 0 {
		return startPos - 1, true
	}

	if isLast {
		// Last keyword: last part must end at position n-1
		// With numParts parts, starting position p = n - numParts
		p := n - numParts
		if p < startPos || p < 0 {
			return 0, false
		}
		for i, part := range parts {
			idx := p + i
			if idx >= n {
				return 0, false
			}
			if part != "" && !containsCI(components[idx], part) {
				return 0, false
			}
		}
		return p + numParts - 1, true
	} else {
		// Non-last keyword: find any starting position >= startPos
		maxStart := n - numParts
		if maxStart < 0 {
			return 0, false
		}
		for p := startPos; p <= maxStart; p++ {
			ok := true
			for i, part := range parts {
				idx := p + i
				if idx >= n {
					ok = false
					break
				}
				if part != "" && !containsCI(components[idx], part) {
					ok = false
					break
				}
			}
			if ok {
				return p + numParts - 1, true
			}
		}
		return 0, false
	}
}

func containsCI(haystack, needle string) bool {
	if needle == "" {
		return true
	}
	return strings.Contains(strings.ToLower(haystack), strings.ToLower(needle))
}

// Config
func dataDir() string {
	if d := os.Getenv("_ZO_DATA_DIR"); d != "" {
		return d
	}
	if xdg := os.Getenv("XDG_DATA_HOME"); xdg != "" {
		return xdg
	}
	home, err := os.UserHomeDir()
	if err == nil {
		return filepath.Join(home, ".local", "share")
	}
	return "."
}

func dbPath() string {
	return filepath.Join(dataDir(), "db.zo")
}

func maxAge() float64 {
	if s := os.Getenv("_ZO_MAXAGE"); s != "" {
		if v, err := strconv.ParseFloat(s, 64); err == nil {
			return v
		}
	}
	return 10000.0
}

func resolveSymlinks() bool {
	return os.Getenv("_ZO_RESOLVE_SYMLINKS") == "1"
}

func echoEnabled() bool {
	return os.Getenv("_ZO_ECHO") == "1"
}

func excludeDirs() []string {
	home, _ := os.UserHomeDir()
	defaultExclude := home
	raw := os.Getenv("_ZO_EXCLUDE_DIRS")
	if raw == "" {
		raw = defaultExclude
	}
	if raw == "" {
		return nil
	}
	parts := strings.Split(raw, ":")
	var result []string
	for _, p := range parts {
		if p != "" {
			result = append(result, p)
		}
	}
	return result
}

func fzfOpts() string {
	return os.Getenv("_ZO_FZF_OPTS")
}

func isExcluded(path string, excludes []string) bool {
	for _, pattern := range excludes {
		if globMatch(pattern, path) {
			return true
		}
	}
	return false
}

// Simple glob matching (supports * and ? wildcards)
func globMatch(pattern, s string) bool {
	// Use filepath.Match for simple glob matching
	matched, err := filepath.Match(pattern, s)
	if err != nil {
		return pattern == s
	}
	return matched
}

