func main() {
	args := os.Args[1:]

	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "Usage: %s <COMMAND>\n\nFor more information, try '--help'.\n", os.Args[0])
		os.Exit(2)
	}

	switch args[0] {
	case "--help", "-h":
		printHelp()
		return
	case "--version", "-V":
		fmt.Printf("zoxide %s\n", version)
		return
	case "add":
		runAdd(args[1:])
	case "edit":
		runEdit(args[1:])
	case "import":
		runImport(args[1:])
	case "init":
		runInit(args[1:])
	case "query":
		runQuery(args[1:])
	case "remove":
		runRemove(args[1:])
	default:
		fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\nUsage: %s <COMMAND>\n\nFor more information, try '--help'.\n", args[0], os.Args[0])
		os.Exit(2)
	}
}

func runAdd(args []string) {
	var paths []string
	scoreIncrement := 1.0

	i := 0
	for i < len(args) {
		switch args[i] {
		case "--help", "-h":
			printSubHelp("add")
			return
		case "--version", "-V":
			fmt.Printf("zoxide-add %s\n", version)
			return
		case "-s", "--score":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--score <SCORE>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			v, err := strconv.ParseFloat(args[i], 64)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--score <SCORE>'\n", args[i])
				os.Exit(2)
			}
			scoreIncrement = v
			i++
		case "--":
			i++
			paths = append(paths, args[i:]...)
			i = len(args)
		default:
			paths = append(paths, args[i])
			i++
		}
	}

	if len(paths) == 0 {
		fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <PATHS>...\n\nUsage: %s add <PATHS>...\n\nFor more information, try '--help'.\n", os.Args[0])
		os.Exit(2)
	}

	excl := excludeDirs()
	resolve := resolveSymlinks()
	maxAgeVal := maxAge()
	dbFile := dbPath()

	db, err := LoadDatabase(dbFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "zoxide: %v\n", err)
		os.Exit(1)
	}

	for _, pathStr := range paths {
		var canonical string
		if resolve {
			c, err := filepath.EvalSymlinks(pathStr)
			if err != nil {
				fmt.Fprintf(os.Stderr, "zoxide: not a directory: %s\n", pathStr)
				os.Exit(1)
			}
			canonical = c
		} else {
			info, err := os.Stat(pathStr)
			if err != nil || !info.IsDir() {
				fmt.Fprintf(os.Stderr, "zoxide: not a directory: %s\n", pathStr)
				os.Exit(1)
			}
			canonical = pathStr
		}

		info, err := os.Stat(canonical)
		if err != nil || !info.IsDir() {
			fmt.Fprintf(os.Stderr, "zoxide: not a directory: %s\n", pathStr)
			os.Exit(1)
		}

		if isExcluded(canonical, excl) {
			continue
		}

		db.Add(canonical, scoreIncrement, maxAgeVal)
	}

	if err := db.Save(dbFile); err != nil {
		fmt.Fprintf(os.Stderr, "zoxide: %v\n", err)
		os.Exit(1)
	}
}

func runEdit(args []string) {
	for _, a := range args {
		if a == "--help" || a == "-h" {
			printSubHelp("edit")
			return
		}
		if a == "--version" || a == "-V" {
			fmt.Printf("zoxide-edit %s\n", version)
			return
		}
	}

	dbFile := dbPath()
	db, err := LoadDatabase(dbFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "zoxide: %v\n", err)
		os.Exit(1)
	}

	now := currentTime()
	var entries []*Entry
	for _, e := range db.Entries {
		info, err := os.Stat(e.Path)
		if err == nil && info.IsDir() {
			entries = append(entries, e)
		}
	}
	sort.Slice(entries, func(i, j int) bool {
		fi := entries[i].Frecency(now)
		fj := entries[j].Frecency(now)
		if fi != fj {
			return fi > fj
		}
		return entries[i].Timestamp > entries[j].Timestamp
	})

	var lines []string
	for _, e := range entries {
		lines = append(lines, fmt.Sprintf("%6.1f %s", e.Frecency(now), e.Path))
	}
	input := strings.Join(lines, "\n")

	opts := fzfOpts()
	selected, err := runFzf(input, opts, true)
	if err != nil {
		fmt.Fprintf(os.Stderr, "zoxide: %v\n", err)
		os.Exit(1)
	}
	if selected == "" {
		return
	}

	for _, line := range strings.Split(selected, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		// Parse "  score path" format
		parts := strings.SplitN(line, " ", 2)
		if len(parts) >= 2 {
			path := strings.TrimSpace(parts[1])
			db.Remove(path)
		}
	}

	if err := db.Save(dbFile); err != nil {
		fmt.Fprintf(os.Stderr, "zoxide: %v\n", err)
		os.Exit(1)
	}
}

func runFzf(input string, opts string, multi bool) (string, error) {
	// Check if fzf is available
	if _, err := exec.LookPath("fzf"); err != nil {
		return "", fmt.Errorf("could not find fzf, is it installed?")
	}

	fzfArgs := []string{"--no-sort"}
	if multi {
		fzfArgs = append(fzfArgs, "--multi")
	}
	if opts != "" {
		fzfArgs = append(fzfArgs, strings.Fields(opts)...)
	}

	cmd := exec.Command("fzf", fzfArgs...)
	cmd.Stdin = strings.NewReader(input)
	cmd.Stderr = os.Stderr
	out, err := cmd.Output()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		return "", fmt.Errorf("fzf error: %w", err)
	}
	return strings.TrimRight(string(out), "\n"), nil
}

func runImport(args []string) {
	var fromApp string
	var merge bool
	var importPath string

	i := 0
	for i < len(args) {
		switch args[i] {
		case "--help", "-h":
			printSubHelp("import")
			return
		case "--version", "-V":
			fmt.Printf("zoxide-import %s\n", version)
			return
		case "--from":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--from <FROM>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			fromApp = args[i]
			i++
		case "--merge":
			merge = true
			i++
		default:
			if strings.HasPrefix(args[i], "--from=") {
				fromApp = strings.TrimPrefix(args[i], "--from=")
				i++
			} else {
				importPath = args[i]
				i++
			}
		}
	}

	if fromApp == "" {
		fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  --from <FROM>\n\nUsage: %s import --from <FROM> <PATH>\n\nFor more information, try '--help'.\n", os.Args[0])
		os.Exit(2)
	}
	if importPath == "" {
		fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <PATH>\n\nUsage: %s import --from <FROM> <PATH>\n\nFor more information, try '--help'.\n", os.Args[0])
		os.Exit(2)
	}

	if fromApp != "autojump" && fromApp != "z" {
		fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--from <FROM>'\n  [possible values: autojump, z]\n\nFor more information, try '--help'.\n", fromApp)
		os.Exit(2)
	}

	dbFile := dbPath()
	db, err := LoadDatabase(dbFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "zoxide: %v\n", err)
		os.Exit(1)
	}

	if len(db.Entries) > 0 && !merge {
		fmt.Fprintf(os.Stderr, "zoxide: current database is not empty, specify --merge to continue anyway\n")
		os.Exit(1)
	}

	content, err := os.ReadFile(importPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "zoxide: could not read import file: %v\n", err)
		os.Exit(1)
	}

	var newEntries []*Entry
	switch fromApp {
	case "z":
		newEntries, err = parseZFormat(string(content))
	case "autojump":
		newEntries, err = parseAutojumpFormat(string(content))
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "zoxide: %v\n", err)
		os.Exit(1)
	}

	if merge {
		for _, ne := range newEntries {
			found := false
			for _, e := range db.Entries {
				if e.Path == ne.Path {
					e.Rank += ne.Rank
					if ne.Timestamp > e.Timestamp {
						e.Timestamp = ne.Timestamp
					}
					found = true
					break
				}
			}
			if !found {
				db.Entries = append(db.Entries, ne)
			}
		}
	} else {
		db.Entries = newEntries
	}

	if err := db.Save(dbFile); err != nil {
		fmt.Fprintf(os.Stderr, "zoxide: %v\n", err)
		os.Exit(1)
	}
}

func parseZFormat(content string) ([]*Entry, error) {
	var entries []*Entry
	scanner := bufio.NewScanner(strings.NewReader(content))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, "|", 3)
		if len(parts) < 2 {
			continue
		}
		path := parts[0]
		rank, _ := strconv.ParseFloat(parts[1], 64)
		var ts uint64
		if len(parts) >= 3 {
			t, _ := strconv.ParseUint(parts[2], 10, 64)
			ts = t
		}
		entries = append(entries, &Entry{Path: path, Rank: rank, Timestamp: ts})
	}
	return entries, nil
}

func parseAutojumpFormat(content string) ([]*Entry, error) {
	var entries []*Entry
	scanner := bufio.NewScanner(strings.NewReader(content))
	for scanner.Scan() {
		line := scanner.Text()
		if strings.TrimSpace(line) == "" {
			continue
		}
		parts := strings.SplitN(line, "\t", 2)
		if len(parts) < 2 {
			continue
		}
		weight, _ := strconv.ParseFloat(strings.TrimSpace(parts[0]), 64)
		path := strings.TrimRight(parts[1], "\r")
		// Convert autojump weight using sigmoid function
		rank := 1.0 / (1.0 + math.Exp(-weight))
		entries = append(entries, &Entry{Path: path, Rank: rank, Timestamp: 0})
	}
	return entries, nil
}

func runQuery(args []string) {
	var keywords []string
	var all, interactive, list, score bool
