	raw := os.Getenv("_ZO_EXCLUDE_DIRS")
	if raw == "" {
		raw = defaultExclude
	}
	if raw == "" {
		return nil
	}
	parts := strings.Split(raw, ":")
	var result []string
	for _, p := range parts {
		if p != "" {
			result = append(result, p)
		}
	}
	return result
}

func fzfOpts() string {
