		}
		e := results[0]
		if score {
			fmt.Printf("%6.1f %s\n", e.Frecency(now), e.Path)
		} else {
			fmt.Println(e.Path)
		}
	}
}

func runRemove(args []string) {
	var paths []string

	i := 0
	for i < len(args) {
		switch args[i] {
		case "--help", "-h":
			printSubHelp("remove")
			return
		case "--version", "-V":
