// Simple glob matching (supports * and ? wildcards)
func globMatch(pattern, s string) bool {
	// Use filepath.Match for simple glob matching
	matched, err := filepath.Match(pattern, s)
	if err != nil {
		return pattern == s
	}
	return matched
